import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  MessageCircle, X, User, Clock, Check, CheckCheck, Send 
} from 'lucide-react';
import { io } from 'socket.io-client';
import axiosInstance from '../';

const ChatModal = ({ currentUser, isAuthenticated, onClose }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [conversation, setConversation] = useState(null);
  const [adminInfo, setAdminInfo] = useState(null);
  const [socket, setSocket] = useState(null);
  const messagesEndRef = useRef(null);

  const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';

  // Initialiser Socket.io
  useEffect(() => {
    if (isAuthenticated && currentUser) {
      const newSocket = io(SOCKET_URL, {
        auth: { token: localStorage.getItem('authToken') },
        transports: ['websocket']
      });

      newSocket.on('connect', () => {
        console.log('🟢 Connecté au serveur de chat');
        if (conversation) {
          newSocket.emit('joinConversation', conversation.id);
        }
      });

      newSocket.on('receiveMessage', handleNewMessage);
      newSocket.on('userTyping', data => {
        if (data.conversationId === conversation?.id && data.userId !== currentUser.id) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 3000);
        }
      });

      newSocket.on('messageRead', data => {
        updateMessageStatus(data.messageIds, 'read');
      });

      setSocket(newSocket);

      return () => newSocket.disconnect();
    }
  }, [isAuthenticated, currentUser, conversation]);

  // Charger la conversation au démarrage
  useEffect(() => {
    if (isAuthenticated && currentUser) loadOrCreateConversation();
  }, [isAuthenticated, currentUser]);

  const loadOrCreateConversation = async () => {
    try {
      setIsLoading(true);

      // Récupérer la première conversation ouverte
      const convResponse = await axiosInstance.get('/messages/conversations');
      let convData = convResponse.data.conversations?.[0] || null;

      if (!convData) {
        // Créer une conversation avec un admin
        const adminsResponse = await axiosInstance.get('/users/admins');
        const adminId = adminsResponse.data.admins?.[0]?.id || 1;

        const newConv = await axiosInstance.post('/messages/conversations/create', { admin_id: adminId });
        convData = newConv.data.conversation;
      }

      if (convData) {
        setConversation(convData);
        await loadMessages(convData.id);

        // Charger infos admin
        if (convData.admin_id) {
          const adminRes = await axiosInstance.get(`/users/${convData.admin_id}`);
          if (adminRes.data.success) setAdminInfo(adminRes.data.user);
        }
      }

    } catch (err) {
      console.error('Erreur chat:', err);
      setMessages([{
        id: 'default',
        content: 'Erreur lors du chargement du chat. Veuillez réessayer.',
        created_at: new Date(),
        sender: { first_name: 'Système', role: 'system' },
        is_read: true
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const loadMessages = async (conversationId) => {
    try {
      const res = await axiosInstance.get(`/messages/conversations/${conversationId}/messages`);
      if (res.data.success) setMessages(res.data.messages || []);
    } catch (err) {
      console.error('Erreur loadMessages:', err);
    }
  };

  const handleNewMessage = (message) => {
    setMessages(prev => [...prev, message]);
    scrollToBottom();
  };

  const updateMessageStatus = (messageIds, status) => {
    setMessages(prev => prev.map(msg =>
      messageIds.includes(msg.id) ? { ...msg, is_read: status === 'read' } : msg
    ));
  };

  const handleSendMessage = async () => {
    if (!inputMessage.trim() || !conversation) return;

    const messageData = { content: inputMessage.trim() };
    try {
      const res = await axiosInstance.post(`/messages/conversations/${conversation.id}/messages`, messageData);
      if (res.data.success) {
        handleNewMessage(res.data.message);
        if (socket) socket.emit('sendMessage', { conversationId: conversation.id, message: res.data.message });
        setInputMessage('');
      }
    } catch (err) {
      console.error('Erreur sendMessage:', err);
    }
  };

  const handleTyping = () => {
    if (socket && conversation) {
      socket.emit('typing', { conversationId: conversation.id, userId: currentUser.id });
    }
  };

  const handleKeyPress = e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } };
  const scrollToBottom = () => { messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }); };
  useEffect(() => { scrollToBottom(); }, [messages]);

  const formatTime = dateStr => new Date(dateStr).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

  if (!isAuthenticated || !currentUser) {
    return (
      <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50">
        <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
              <MessageCircle className="h-5 w-5" />
            </div>
            <div>
              <h3 className="font-bold">Support Nexus</h3>
              <p className="text-xs opacity-90">Connectez-vous pour chatter</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-lg"><X className="h-5 w-5" /></button>
        </div>
        <div className="p-6 text-center">
          <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-300 mb-4">Connectez-vous pour discuter avec notre équipe de support</p>
          <button onClick={() => navigate('/login')} className="w-full py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:opacity-90 transition-opacity">Se connecter</button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50">
      {/* Header */}
      <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            {adminInfo?.avatar ? <img src={adminInfo.avatar} alt={adminInfo.first_name} className="h-10 w-10 rounded-full border-2 border-white/30"/> : <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center"><User className="h-5 w-5"/></div>}
            <div>
              <h3 className="font-bold">{adminInfo ? `${adminInfo.first_name} ${adminInfo.last_name}` : 'Support Nexus'}</h3>
              <p className="text-xs opacity-90">{adminInfo?.role === 'admin' ? 'Conseiller • En ligne' : 'En attente de conseiller'}</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-lg"><X className="h-5 w-5"/></button>
        </div>
        <div className="mt-2 flex items-center justify-between text-xs">
          <span className="bg-white/20 px-2 py-1 rounded">Ticket: #{conversation?.id?.toString().substring(0,8)}</span>
          <span className="flex items-center"><div className="h-2 w-2 rounded-full bg-green-400 mr-1 animate-pulse"></div>En ligne</span>
        </div>
      </div>

      {/* Messages */}
      <div className="h-64 sm:h-72 p-4 overflow-y-auto">
        {isLoading ? <div className="flex items-center justify-center h-full"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500"></div></div> :
        <div className="space-y-3">
          {messages.map(msg => (
            <div key={msg.id} className={`flex ${msg.sender_id === currentUser.id ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] p-3 rounded-2xl ${msg.sender_id === currentUser.id ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none' : 'bg-gray-100 dark:bg-neutral-800 text-gray-900 dark:text-white rounded-bl-none'}`}>
                {msg.sender_id !== currentUser.id && <div className="flex items-center space-x-2 mb-1"><span className="text-xs font-medium">{msg.sender?.first_name || 'Support'}</span></div>}
                <p className="text-sm">{msg.content}</p>
                <div className={`flex items-center justify-between mt-2 ${msg.sender_id === currentUser.id ? 'text-white/80' : 'text-gray-500'}`}>
                  <span className="text-xs">{formatTime(msg.created_at)}</span>
                  {msg.sender_id === currentUser.id && <div className="flex items-center space-x-1">{msg.is_read ? <CheckCheck className="h-3 w-3 text-blue-300"/> : <Check className="h-3 w-3"/>}</div>}
                </div>
              </div>
            </div>
          ))}
          {isTyping && <div className="flex justify-start"><div className="bg-gray-100 dark:bg-neutral-800 rounded-2xl rounded-bl-none p-3"><span className="text-xs text-gray-500">{adminInfo?.first_name} écrit...</span></div></div>}
          <div ref={messagesEndRef}/>
        </div>}
      </div>

      {/* Input */}
      <div className="p-3 border-t dark:border-neutral-800">
        <div className="flex items-center space-x-2">
          <input type="text" value={inputMessage} onChange={e => { setInputMessage(e.target.value); handleTyping(); }} onKeyPress={handleKeyPress} placeholder="Écrivez votre message..." className="flex-1 pl-4 pr-12 py-3 rounded-xl border dark:border-neutral-700 bg-white dark:bg-neutral-800 focus:outline-none focus:ring-2 focus:ring-primary-500"/>
          <button onClick={handleSendMessage} disabled={!inputMessage.trim()} className="p-3 rounded-xl bg-primary-500 text-white hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed"><Send className="h-5 w-5"/></button>
        </div>
        <div className="mt-2 text-xs text-gray-500 text-center"><Clock className="inline h-3 w-3 mr-1"/>Temps de réponse moyen : 2-5 minutes</div>
      </div>
    </div>
  );
};

export default ChatModal;
